import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import UnifiedNavbar from "../components/UnifiedNavbar";
import API from "../services/api";

function AdminDashboard(){
  const [stats, setStats] = useState({
    totalStudents: 0,
    totalMenus: 0,
    todayPresent: 0,
    todayAbsent: 0,
    todayLeave: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      setLoading(true);
      
      // Fetch total students
      const studentsRes = await API.get("/student");
      const students = studentsRes.data || [];

      // Fetch today's attendance
      const today = new Date().toISOString().split('T')[0];
      const attendanceRes = await API.get("/attendance", {
        params: { date: today }
      });
      const todayAttendance = attendanceRes.data || [];

      const newStats = {
        totalStudents: students.length,
        totalMenus: 0, // Will update if menu API is available
        todayPresent: todayAttendance.filter(a => a.status === "Present").length,
        todayAbsent: todayAttendance.filter(a => a.status === "Absent").length,
        todayLeave: todayAttendance.filter(a => a.status === "Leave").length
      };

      // Try to fetch menus
      try {
        const menusRes = await API.get("/menu");
        newStats.totalMenus = menusRes.data?.length || 0;
      } catch (e) {
        newStats.totalMenus = 0;
      }

      setStats(newStats);
    } catch (error) {
      console.log("Error fetching stats");
    } finally {
      setLoading(false);
    }
  };

  return(
    <div className="dashboard">
      <UnifiedNavbar />
      <div className="main-content">
        <h1>Admin Dashboard</h1>
        
        <div className="stats-overview">
          <div className="stat-card">
            <span className="stat-icon">👥</span>
            <div className="stat-info">
              <span className="stat-value">{stats.totalStudents}</span>
              <span className="stat-label">Total Students</span>
            </div>
          </div>
          <div className="stat-card">
            <span className="stat-icon">📋</span>
            <div className="stat-info">
              <span className="stat-value">{stats.todayPresent}</span>
              <span className="stat-label">Present Today</span>
            </div>
          </div>
          <div className="stat-card">
            <span className="stat-icon">❌</span>
            <div className="stat-info">
              <span className="stat-value">{stats.todayAbsent}</span>
              <span className="stat-label">Absent Today</span>
            </div>
          </div>
          <div className="stat-card">
            <span className="stat-icon">🚫</span>
            <div className="stat-info">
              <span className="stat-value">{stats.todayLeave}</span>
              <span className="stat-label">Leave Today</span>
            </div>
          </div>
        </div>

        <div className="cards">
          <div className="card">
            <h3>Student List</h3>
            <p>View all registered students</p>
            <Link to="/students" className="card-link">View Students</Link>
          </div>

          <div className="card">
            <h3>Manage Menu</h3>
            <p>Create, edit, and manage daily menus</p>
            <Link to="/edit-menu" className="card-link">Manage Menu</Link>
          </div>

          <div className="card">
            <h3>Attendance Management</h3>
            <p>Track and manage student attendance</p>
            <Link to="/attendance" className="card-link">View Attendance</Link>
          </div>
        </div>
      </div>
  </div>
  );
}

export default AdminDashboard
